    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Comparatives with More and Less';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Comparatives with More and Less','Longer adjectives usually take more or less before the adjective.','Objective: Use more or less with longer adjectives to compare two things.
Content: Use more ... than for a higher quality and less ... than for a lower quality.
Examples:
- The train is more comfortable than the bus.
- This route is less dangerous than that road.
Common errors and corrections:
- Do not add -er to most long adjectives.
- Keep than after the comparative when the second item is named.
Guided practice: Count the adjective syllables, then choose more or less and add than.
Summary: Use more or less plus a longer adjective for a comparison.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Comparatives with More and Less','Longer adjectives usually take more or less before the adjective.','Objective: Use more or less with longer adjectives to compare two things.
Content: Use more ... than for a higher quality and less ... than for a lower quality.
Examples:
- The train is more comfortable than the bus.
- This route is less dangerous than that road.
Common errors and corrections:
- Do not add -er to most long adjectives.
- Keep than after the comparative when the second item is named.
Guided practice: Count the adjective syllables, then choose more or less and add than.
Summary: Use more or less plus a longer adjective for a comparison.','GRAMMAR',2,10,FALSE) RETURNING id INTO v_lesson_revision_id;
