    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Superlatives and the','A superlative compares one person or thing with a stated group.','Objective: Use -est or most with the to identify one item at the top or bottom of a group.
Content: Use the plus -est with many short adjectives and the most or least with longer adjectives.
Examples:
- This is the smallest room.
- It is the most comfortable chair in the office.
Common errors and corrections:
- Do not omit the before a superlative.
- Use a group such as in the class or in the town.
Guided practice: Find the comparison group, then choose the form with the.
Summary: Superlatives use the and identify one extreme member of a group.','GRAMMAR',3,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
