    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Irregular Forms and Comparison Modifiers','Some adjectives are irregular, and modifiers show the size of a difference.','Objective: Use better, worse, the best, the worst, and common comparative modifiers.
Content: Use better and worse for comparative meaning, the best and the worst for a group, and a bit, much, or far before comparatives.
Examples:
- This plan is much better than the old one.
- It is the worst day of the week.
Common errors and corrections:
- Do not use the best when comparing only two items.
- Use much, far, or a bit before the comparative, not the superlative.
Guided practice: Decide whether the sentence compares two items or ranks a group before choosing the form.
Summary: Irregular adjectives and modifiers make comparisons more precise.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
